package com.kamonity.controller;

import com.kamonity.model.*;
import com.kamonity.repository.*;
import com.kamonity.service.NotificationService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.time.LocalDateTime;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

@RestController @RequestMapping("/api/v1")
public class PostController {
    private final PostRepository posts; private final UserRepository users; private final PostVoteRepository votes; private final PointTransactionRepository transactions; private final AuditEventRepository audit; private final PostCommentRepository comments; private final PostReportRepository reports; private final UserContentHashRepository hashes; private final NotificationService notifications; private final MediaAssetRepository mediaAssets;
    public PostController(PostRepository posts,UserRepository users,PostVoteRepository votes,PointTransactionRepository transactions,AuditEventRepository audit,PostCommentRepository comments,PostReportRepository reports,UserContentHashRepository hashes,NotificationService notifications,MediaAssetRepository mediaAssets){this.posts=posts;this.users=users;this.votes=votes;this.transactions=transactions;this.audit=audit;this.comments=comments;this.reports=reports;this.hashes=hashes;this.notifications=notifications;this.mediaAssets=mediaAssets;}
    @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","service","kombackend");}
    @GetMapping("/users") public List<UserSummary> users(){return users.findAll().stream().map(u->new UserSummary(u.getId(),u.getName(),u.getPoints())).toList();}
    @GetMapping("/users/{userId}/votes") public List<Long> userVotes(@PathVariable Long userId){if(!users.existsById(userId))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return votes.findAllByUserId(userId).stream().map(PostVote::getPostId).toList();}
    @GetMapping("/posts") public List<Post> posts(){return posts.findAllByOrderByCreatedAtDesc().stream().filter(Post::isVisible).filter(p->p.getMediaAsset()==null||"READY".equals(p.getMediaAsset().getStatus())).toList();}
    @PostMapping("/posts") @ResponseStatus(HttpStatus.CREATED) @Transactional public Post create(@Valid @RequestBody CreatePost body){
        User actor=users.findById(body.authorId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));String clean=Jsoup.clean(body.content()==null?"":body.content(),Safelist.none()).trim();if(clean.isBlank()&&body.mediaAssetId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Text or media is required");
        if(!clean.isBlank()){String hash=sha256(clean.toLowerCase().replaceAll("\\s+"," "));if(hashes.existsByUser_IdAndContentHashAndCreatedAtAfter(actor.getId(),hash,Instant.now().minusSeconds(86400)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Duplicate post content within 24 hours");}
        Post post=new Post(actor.getName(),clean,1,0,0,0,LocalDateTime.now());post.setAuthor(actor);if(body.mediaAssetId()!=null){MediaAsset asset=mediaAssets.findById(body.mediaAssetId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Media not found"));if(!asset.getOwner().getId().equals(actor.getId())||!"READY".equals(asset.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Media must be owned by author and READY");post.setMediaAsset(asset);}posts.save(post);if(!clean.isBlank())hashes.save(new UserContentHash(actor,sha256(clean.toLowerCase().replaceAll("\\s+"," ")),"POST",post.getId()));actor.awardPoint();transactions.save(new PointTransaction(actor,actor,post,"POST_CREATED",1));audit.save(new AuditEvent(actor,"POST_CREATED","POST",post.getId().toString(),"{}"));try{notifications.bufferActivity(actor.getId(),post.getId(),"POST");}catch(Exception ignored){}return post;
    }
    @PostMapping("/posts/{id}/vote") @Transactional public Post vote(@PathVariable Long id,@Valid @RequestBody VoteRequest req){User voter=users.findById(req.userId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));Post post=posts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(votes.existsByUser_IdAndPost_Id(voter.getId(),id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Already voted");try{votes.saveAndFlush(new PostVote(voter,post));}catch(DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Already voted");}post.addVote();voter.awardPoint();transactions.save(new PointTransaction(voter,voter,post,"POST_VOTED",1));audit.save(new AuditEvent(voter,"POST_VOTED","POST",id.toString(),"{}"));try{notifications.bufferActivity(voter.getId(),id,"VOTE");}catch(Exception ignored){}return post;}
    @GetMapping("/posts/{postId}/comments") public List<CommentResponse> comments(@PathVariable Long postId){if(!posts.existsById(postId))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return comments.findAllByPostIdOrderByCreatedAtAsc(postId).stream().map(c->new CommentResponse(c.getId(),c.getAuthor().getId(),c.getAuthorName(),c.getContent(),c.getCreatedAt().toString())).toList();}
    @PostMapping("/posts/{postId}/comments") @ResponseStatus(HttpStatus.CREATED) @Transactional public CommentResponse comment(@PathVariable Long postId,@Valid @RequestBody CreateComment req){Post p=posts.findById(postId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));User actor=users.findById(req.userId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));String text=Jsoup.clean(req.content(),Safelist.none()).trim();if(text.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST);PostComment c=comments.save(new PostComment(p,actor,text));p.incrementComments();actor.awardPoint();User author=p.getAuthor()!=null?p.getAuthor():users.findByName(p.getAuthorName()).orElseThrow();author.addPoints(2);transactions.save(new PointTransaction(actor,actor,p,"COMMENT_CREATED",1));transactions.save(new PointTransaction(actor,author,p,"COMMENT_RECEIVED",2));audit.save(new AuditEvent(actor,"COMMENT_CREATED","POST",postId.toString(),"{}"));try{notifications.bufferActivity(actor.getId(),postId,"COMMENT");}catch(Exception ignored){}return new CommentResponse(c.getId(),actor.getId(),actor.getName(),c.getContent(),c.getCreatedAt().toString());}
    @PostMapping("/posts/{id}/report") @Transactional public ReportResponse report(@PathVariable Long id,@Valid @RequestBody ReportRequest req){User reporter=users.findById(req.userId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));Post p=posts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if("PERMANENTLY_DEACTIVATED".equals(p.getStatus())||reports.existsByPost_IdAndReporter_Id(id,reporter.getId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Already reported or post locked");if(!List.of("SPAM","ABUSE","MISINFORMATION","HARASSMENT","OTHER").contains(req.reasonCode()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid reason");reports.save(new PostReport(p,reporter,req.reasonCode(),req.details()));p.recordReport();long total=reports.countByPost_Id(id),hour=reports.countByPost_IdAndCreatedAtAfter(id,Instant.now().minusSeconds(3600));if(total>=10)p.setStatus("PERMANENTLY_DEACTIVATED");else if(hour>=5){p.setStatus("TEMPORARILY_HIDDEN");p.freezePoints();}User author=p.getAuthor()!=null?p.getAuthor():users.findByName(p.getAuthorName()).orElseThrow();if(!p.isPointsFrozen()&&total<10){author.addPoints(-1);reports.findByPost_IdAndReporter_Id(id,reporter.getId()).ifPresent(PostReport::deductPoint);transactions.save(new PointTransaction(reporter,author,p,"POST_REPORTED",-1));}audit.save(new AuditEvent(reporter,"POST_REPORTED","POST",id.toString(),"{}"));try{notifications.bufferActivity(reporter.getId(),id,"REPORT");}catch(Exception ignored){}return new ReportResponse(id,(int)total,p.getStatus());}
    @GetMapping("/leaderboard") public List<LeaderboardEntry> leaderboard(){return users.findAll().stream().map(u->new LeaderboardEntry(u.getId(),u.getName(),u.getPoints())).sorted(Comparator.comparingInt(LeaderboardEntry::points).reversed()).toList();}
    private String sha256(String input){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    public record CreatePost(@NotNull Long authorId,@Size(max=1800) String content,Long mediaAssetId){} public record VoteRequest(@NotNull Long userId){} public record CreateComment(@NotNull Long userId,@NotBlank @Size(max=2000) String content){} public record CommentResponse(Long id,Long userId,String authorName,String content,String createdAt){} public record UserSummary(Long id,String name,int points){} public record LeaderboardEntry(Long userId,String name,int points){} public record ReportRequest(@NotNull Long userId,@NotNull String reasonCode,@Size(max=1000) String details){} public record ReportResponse(Long postId,int reportCount,String status){}
}
